///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.onload();
        try {
            if ($c.util.getComponent('dma_RegisterReq').get('prtdepoShrsDsp')== null) {
                for (let i = 0; i < (console.warn("[sdd] unresolved:dmap-member:" + "prtdepoShrsDsp @ dma_RegisterReq.prtdepoShrsDsp"), $c.util.getComponent('dma_RegisterReq')).length; i++) {

                }
            } else {

            }
        } catch (err2) { $c.exception.handleError(err2, { notify: 'none', context: 'jldfil05010' }); return; }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05010.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05010' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.maxLenCheckVars =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05010' }); }

try { scwin.maxLenCheckNames =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05010' }); }

try { scwin.maxLenCheckMax =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05010' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_sessionFill();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05010.onpageload' });
    }
};

