/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.loadForm(r["bzProcsNo"], r["bybzprocsSeq"], r["prtdepoPrnTpCd"], r["prtdepoMms"], r["nm"], r["resdbzRegNo"], r["humanRel"], r["prtdepoObjKindCd"], r["prtdepoObjTpCd"], r["prtdepoObjTpMiscContn"], r["prtdepoShrs"], r["prtdepoRto"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

/**
 * @method
 * @name onChangeObjKindCd
 * @description on Change Obj Kind Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.onChangeObjKindCd = function () {
    try {
        let defaultitem;
        const valueItem1 = "전환우선주:1|상환우선주:2|상환전환우선주:3|기타:6";
        const valueItem2 = "전환사채:4|신주인수권부사채:5|기타:6";
        const selectCtrl = $c.util.getComponent('slc_prtdepoObjTpCd');
        const sval = $c.util.getComponent('slc_prtdepoObjKindCd').getValue();
        let i;
        for (i = selectCtrl.options.length; i >= 0; i--) {
            selectCtrl.options[i] = null;
        }
        if (sval !== "1") {
            if (sval === "2") {
                defaultitem = valueItem1.split("|");
            } else {
                defaultitem = valueItem2.split("|");
            }
            for (i = 0; i < defaultitem.length; i++) {
                eld = defaultitem[i].split(":");
                selectCtrl.options[i] = new Option(eld[0]);
                selectCtrl.options[i].value = eld[1];
            }
        } else {
            selectCtrl.options[0] = new Option("해당사항없음");
            selectCtrl.options[0].value = "";
        }
        selectCtrl.options[0].selected = true;
        scwin.onChangeObjTpCd();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil05010c.onChangeObjKindCd" });
    }
};

/**
 * @method
 * @name onChangeObjTpCd
 * @description on Change Obj Tp Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.onChangeObjTpCd = function () {
    try {
        if ($c.util.getComponent('slc_prtdepoObjTpCd').getValue()=== "6") {
            $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setDisabled(false);
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        } else {
            $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setValue("");
            $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil05010c.onChangeObjTpCd" });
    }
};

/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    try {
        scwin.form = (document.prelistEtcForm || { elements: [] });
        scwin.onChangeObjKindCd();
        if (($c.util.getComponent('dma_RegisterReq').get('nowPage')) > ($c.util.getComponent('dma_RegisterReq').get('billLstSaveStatCd'))) {
            return;
        }
        scwin.onloadDataSet();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil05010c.onload" });
    }
};

/**
 * @method
 * @name onloadDataSet
 * @description onload Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.onloadDataSet = function () {
    /* empty */
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/list/prelistEtc.do",
        ref: "dma_RegisterReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name loadForm
 * @description load Form 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} bybzprocsSeq bybzprocsSeq
 * @param {String} prtdepoPrnTpCd prtdepoPrnTpCd
 * @param {*} prtdepoMms prtdepoMms
 * @param {*} nm nm
 * @param {*} resdbzRegNo resdbzRegNo
 * @param {*} humanRel humanRel
 * @param {String} prtdepoObjKindCd prtdepoObjKindCd
 * @param {String} prtdepoObjTpCd prtdepoObjTpCd
 * @param {*} prtdepoObjTpMiscContn prtdepoObjTpMiscContn
 * @param {*} prtdepoShrs prtdepoShrs
 * @param {*} prtdepoRto prtdepoRto
 * @returns {void}
 * @hidden N
 */
scwin.loadForm = function (bzProcsNo, bybzprocsSeq, prtdepoPrnTpCd, prtdepoMms, nm, resdbzRegNo, humanRel, prtdepoObjKindCd, prtdepoObjTpCd, prtdepoObjTpMiscContn, prtdepoShrs, prtdepoRto) {
    if (bzProcsNo === "SUMPART") {
        return;
    }
    $c.util.getComponent('dma_RegisterReq').set('bybzprocsSeq', bybzprocsSeq);
    (($c.util.getComponent('slc_prtdepoPrnTpCd'))?.setValue?.(prtdepoPrnTpCd));
    $c.util.getComponent('ipt_prtdepoMms').setValue(prtdepoMms);
    $c.util.getComponent('ipt_nm').setValue(nm);
    $c.util.getComponent('ipt_resdbzRegNo').setValue(resdbzRegNo);
    $c.util.getComponent('ipt_humanRel').setValue(humanRel);
    (($c.util.getComponent('slc_prtdepoObjKindCd'))?.setValue?.(prtdepoObjKindCd));
    scwin.onChangeObjKindCd();
    (($c.util.getComponent('slc_prtdepoObjTpCd'))?.setValue?.(prtdepoObjTpCd));
    scwin.onChangeObjTpCd();
    $c.util.getComponent('ipt_prtdepoObjTpMiscContn').setValue(prtdepoObjTpMiscContn);
    $c.util.getComponent('ipt_prtdepoShrs').setValue($c.num.formatNumber(prtdepoShrs));
    $c.util.getComponent('ipt_prtdepoRto').setValue($c.num.formatNumber(prtdepoRto));
    scwin.onloadDataSet();
};

/**
 * @method
 * @name calcRt
 * @description calc Rt 처리
 * @returns {void}
 * @hidden N
 */
scwin.calcRt = function () {
    const tot_stk_cnt = ($c.util.getComponent('dma_RegisterReq').get('sumAll'));
    if (tot_stk_cnt > 0) {
        let rt = scwin.rmComma($c.util.getComponent('ipt_prtdepoShrs').getValue()) / tot_stk_cnt;
        rt = Math.round(rt * 10000) / 100;
        if (rt > 100) {

        } else {
            $c.util.getComponent('ipt_prtdepoRto').setValue(rt);
        }
        $c.util.getComponent('ipt_prtdepoRto').setValue(rt);
    }
};

/**
 * @method
 * @name vailidationLn
 * @description vailidation Ln 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.vailidationLn = async function () {
    if (($c.util.getComponent('ipt_prtdepoMms').getValue() == null ? '' : String($c.util.getComponent('ipt_prtdepoMms').getValue())) === '') {
        await $c.win.alert("보호예수기간을 입력하십시요.");
        $c.util.getComponent("ipt_prtdepoMms").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('ipt_nm').getValue() == null ? '' : String($c.util.getComponent('ipt_nm').getValue())) === '') {
        await $c.win.alert("성명/명칭을 입력하십시요.");
        $c.util.getComponent("ipt_nm").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('ipt_resdbzRegNo').getValue() == null ? '' : String($c.util.getComponent('ipt_resdbzRegNo').getValue())) === '') {
        await $c.win.alert("생년월일/사업자번호/외국인번호를 입력하십시요.");
        $c.util.getComponent("ipt_resdbzRegNo").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (!$c.str.getByteLength($c.util.getComponent('ipt_resdbzRegNo'), 20)) {  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_CheckStringLength — as-is 공통(폼 전역 의존) — 반입 보류
        await $c.win.alert("생년월일/사업자번호/외국인번호가 너무 깁니다.");
        $c.util.getComponent('ipt_resdbzRegNo').select();
        return false;
    }
    if ($c.util.getComponent('slc_prtdepoObjTpCd').getValue()=== "6") {
        if (($c.util.getComponent('ipt_prtdepoObjTpMiscContn').getValue() == null ? '' : String($c.util.getComponent('ipt_prtdepoObjTpMiscContn').getValue())) === '') {
            await $c.win.alert("기타대상구분에 대해 입력하십시요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
    }
    if (($c.util.getComponent('ipt_prtdepoShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_prtdepoShrs').getValue())) === '') {
        await $c.win.alert("보호예수대상주식수를 입력하세요.");
        $c.util.getComponent("ipt_prtdepoShrs").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (!await (async () => { const vars = scwin.maxLenCheckVars || []; const names =  scwin.maxLenCheckNames || []; const maxes =  scwin.maxLenCheckMax || []; for (let i = 0; i < vars.length; i++) { const c = $c.util.getComponent(vars[i]); if (!c || !c.getValue) { continue; } const len = $c.str.getByteLength(String(c.getValue() ?? "")); const max = Number(maxes[i]) || 0; if (max && len > max) { await $c.win.alert(String(names[i]) + "의 최대길이(" + max + ")를 \n" + (len - max) + " Byte 만큼 초과하였습니다.\n수정후 저장하세요"); if (c.setFocus) { c.setFocus(); } return false; } } return true; })()) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (await scwin.vailidationLn() === false) {
        return;
    }
    scwin.form.action = '/list/prelistEtc.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'prelistRegEtc');
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name setInitData
 * @description set Init Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.setInitData = function () {
    scwin.loadForm('123', '1', '1', '22', 'test', '200811', 'tttt', '1', '2', 'dddd', '1212', '1122');
    const tmp = 1234 / 1234;
    $c.util.getComponent('ipt_prtdepoRto').setValue(Math.round(tmp * 10000) / 100);
};

/**
 * @method
 * @name rmComma
 * @description rm Comma 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.rmComma = function (str) {

    //    if( str == null || str == "" || str == 0 ) return '';
    //    if( str == null || str == ""  ) return '';
    if( str == null || str === ""  ) return Number(str);   // 2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg =  new RegExp(",","g");

    return Number(str.replace(reg,''));
};

/**
 * @method
 * @name prelistPageSearch
 * @description prelist Page Search 처리
 * @returns {Promise<void>}
